srcDoc.css:
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body { font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", sans-serif; background: #0F172A; color: #e2e8f0; overflow-y: auto; padding: 4px 6px 16px; }
.title { font-size: 15px; font-weight: 700; color: #f8fafc; margin: 14px 2px 10px; letter-spacing: .01em; }
.empty { color: #64748b; font-size: 13px; padding: 6px 2px 10px; }
.msg { display: block; margin: 10px 0; }
.bubble { width: 100%; padding: 11px 14px; border-radius: 12px; border: 1px solid #334155; background: #1e293b; border-left: 3px solid #475569; }
.msg.pc .bubble { border-left-color: #34d399; }
.msg.cust .bubble { border-left-color: #60a5fa; }
.who { display: flex; justify-content: space-between; gap: 14px; align-items: baseline; margin-bottom: 5px; }
.who .name { font-size: 12px; font-weight: 600; color: #34d399; }
.msg.cust .who .name { color: #93c5fd; }
.who .time { font-size: 11px; color: #94a3b8; white-space: nowrap; }
.body { font-size: 13px; line-height: 1.5; color: #e5e7eb; white-space: pre-wrap; word-break: break-word; }
.att { margin-top: 7px; font-size: 12px; color: #94a3b8; }
.exc { background: #1e293b; border: 1px solid #334155; border-radius: 12px; padding: 13px 14px; margin: 10px 0; }
.exc .lbl { font-size: 13px; color: #f1f5f9; line-height: 1.45; margin-bottom: 10px; }
.chips { display: flex; flex-wrap: wrap; gap: 7px; }
.chip { font-size: 11px; padding: 3px 9px; border-radius: 999px; background: #334155; color: #cbd5e1; }
.chip.s-open { background: #7c2d12; color: #fed7aa; }
.chip.s-resolved { background: #064e3b; color: #a7f3d0; }
.chip.a-yes { background: #064e3b; color: #a7f3d0; }
.chip.a-no { background: #3f3f46; color: #e4e4e7; }

srcDoc.js:
function esc(s){ return (s==null?'':String(s)).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); }
function fmt(d){ if(!d) return ''; try { return new Date(d).toLocaleString('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}); } catch(e){ return String(d); } }
function render(){
  var model = (window.appsmith && appsmith.model) || {};
  var msgs = model.messages || [];
  var excs = model.exceptions || [];
  var h = '';
  h += '<div class="title">Messages</div>';
  if(!msgs.length){ h += '<div class="empty">No messages on this ticket.</div>'; }
  else {
    msgs.forEach(function(m){
      var side = (m.sender === 'payclearly') ? 'pc' : 'cust';
      var att = m.hasAttachments ? '<div class="att">\u{1F4CE} ' + ((m.attachments && m.attachments.length) || 'attachment') + '</div>' : '';
      h += '<div class="msg ' + side + '"><div class="bubble">'
        + '<div class="who"><span class="name">' + esc(m.sentByName || m.sender || 'Unknown') + '</span><span class="time">' + esc(fmt(m.sentAt)) + '</span></div>'
        + '<div class="body">' + esc(m.body || '') + '</div>' + att + '</div></div>';
    });
  }
  h += '<div class="title">Exception items</div>';
  if(!excs.length){ h += '<div class="empty">No exception items on this ticket.</div>'; }
  else {
    excs.forEach(function(e){
      h += '<div class="exc"><div class="lbl">' + esc(e.label || '') + '</div><div class="chips">'
        + '<span class="chip">#' + esc(e.sequence) + '</span>'
        + '<span class="chip s-' + esc(e.state) + '">' + esc(e.state) + '</span>'
        + '<span class="chip a-' + (e.isAnswered ? 'yes' : 'no') + '">' + (e.isAnswered ? 'Answered' : 'Unanswered') + '</span>'
        + (e.answeredAt ? '<span class="chip">Answered ' + esc(fmt(e.answeredAt)) + '</span>' : '')
        + '<span class="chip">Created ' + esc(fmt(e.createdAt)) + '</span>'
        + '</div></div>';
    });
  }
  var root = document.getElementById('root');
  if(root) root.innerHTML = h;
}
appsmith.onReady(function(){ render(); });
appsmith.onModelChange(function(){ render(); });
